package com.estoqueinteligente.report;
import com.estoqueinteligente.product.*;
public class LowStockReportResponse{private final Long id;private final String name,categoryName;private final Integer quantity,minimumStock,quantityToBuy;private final ProductStatus status;public LowStockReportResponse(ProductResponse p){id=p.getId();name=p.getName();categoryName=p.getCategoryName();quantity=p.getQuantity();minimumStock=p.getMinimumStock();quantityToBuy=Math.max(1,minimumStock-quantity);status=p.getStatus();}public Long getId(){return id;}public String getName(){return name;}public String getCategoryName(){return categoryName;}public Integer getQuantity(){return quantity;}public Integer getMinimumStock(){return minimumStock;}public Integer getQuantityToBuy(){return quantityToBuy;}public ProductStatus getStatus(){return status;}}
